namespace GeetaStudio.Api;

internal static class EditorialPage
{
    internal const string Html = """
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Editorial workbench</title>
<style>body{font:16px system-ui;max-width:1200px;margin:2rem auto;padding:1rem}label{display:block;margin:.5rem 0}input,select,textarea,button{font:inherit;padding:.5rem}textarea{width:95%;height:9rem}button{margin:.3rem}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#f4f4f4;padding:1rem}section{border:1px solid #ccc;padding:1rem;margin:1rem 0}table{border-collapse:collapse;width:100%}td,th{padding:.5rem;border:1px solid #ccc;text-align:left}</style></head><body>
<p><a href="/staff/media">Media library</a> · <a href="/staff/trends">Trend evidence, teaching connections and original packages</a></p><h1>Editorial workbench</h1><p>Review the exact text, source evidence and media together. Fixture approval is for local checks; genuine human evaluation and publishing qualification remain required. Publication here creates a local preview only.</p>
<nav><a href="/staff/characters">Character registry and casting</a> · <a href="/staff/evaluation">Quality reviews</a> · <a href="/staff/evidence">Claims and interpretations</a> · <a href="/staff/sources">Source permissions</a></nav>
<label>Tenant <select id="tenant"></select></label><label>Universe <select id="universe"></select></label><button id="load">Load workbench</button><p id="status" role="status">Choose an owned scope.</p>
<section><h2>Draft queue</h2><label>Item <select id="item"></select></label><button id="inspect">Inspect evidence and history</button>
<p id="state"></p><p id="blocks"></p>
<label>Title <input id="title" size="65"></label><label>Current text <textarea id="body"></textarea></label><label>Previous text <textarea id="previous" readonly></textarea></label>
<label>Content kind <select id="kind"><option>Fiction</option><option>Synthetic</option><option>Interpretation</option><option>Translation</option><option>Canonical</option><option>Historical</option></select></label>
<label>Rights <select id="rights"><option>Owned</option><option>Licensed</option><option>Synthetic</option><option>Unverified</option></select></label><label>Edit/source reference <input id="provenance" size="70"></label><button id="edit">Save new revision and invalidate approval</button>
<label>Review action <select id="action"><option>Draft</option><option>Evaluate</option><option>Review</option><option>Approve</option><option>Reject</option><option>Schedule</option><option>PublishDryRun</option><option>Withdraw</option><option>Fail</option></select></label>
<label>Mode <select id="mode"><option>Fixture</option><option>Manual</option></select></label><label>Evidence reference <input id="evidence" placeholder="fixture:check or manual:real-review" size="70"></label>
<label>Evaluation report <select id="report"></select></label><label>Evaluation case <select id="case"></select></label>
<label>Scheduled time (UTC) <input id="scheduled" type="datetime-local"></label><button id="act">Apply role-checked action</button>
<h3>Sources, competing interpretations, audience variants, costs and evaluations</h3><pre id="detail"></pre><h3>Lineage and immutable review history</h3><pre id="lineage"></pre><div id="lineageLinks"></div>
<h3>Preview assets</h3><div id="assets"></div><label>Asset slot <input id="slot" value="voice"></label><label>Media type <select id="mime"><option>audio/wav</option><option>image/png</option><option>video/mp4</option><option>text/plain</option></select></label><input id="file" type="file"><button id="assetSave">Attach or replace preview; invalidate approval</button></section>
<section><h2>Start from a brief or factory draft</h2><label>Key <input id="key"></label><label>Format <select id="format"><option>Article</option><option>Translation</option><option>Episode</option><option>Export</option><option>Post</option></select></label><label>Brief <textarea id="brief"></textarea></label>
<label>Existing content ID (optional) <input id="existing" size="45"></label><label>Subject <select id="subject"></select></label><label>Audience <select id="audience"></select></label><label>Locale <select id="locale"></select></label><button id="start">Start reviewable item</button></section>
<section><h2>Correction queue</h2><label>Claim revision ID <input id="claimId" size="45"></label><label>Source snapshot ID (choose one) <input id="snapshotId" size="45"></label><label>Correction reason <textarea id="reason"></textarea></label><label>Independent reviewed replacement content ID (for Resolve) <input id="replacement" size="45"></label><button id="correct">Find affected derivatives and copies</button><div id="corrections"></div></section>
<section><h2>Manual trend review</h2><p>Feed discovery is M15. Review only owned submitted evidence here; missing matches/transcripts and stale or unverified claims keep candidates on hold.</p><div id="trends"></div><details><summary>Import a manually prepared candidate</summary><textarea id="trendInput" placeholder="Owned candidate JSON with source/claim IDs, timestamps, cost, cast and script preview"></textarea><button id="trendSave">Submit candidate</button></details></section>
<section><h2>Provider route administration</h2><p>Administrator only. Credentials are masked; no live call or budget spend occurs here. Configure profiles in <a href="/staff/ai">AI administration</a>, or inspect <a href="/api/v1/runtime/providers">M1 runtime profiles</a>.</p>
<button id="providersLoad">Load qualified profiles and route versions</button><pre id="providers"></pre><label>Route <select id="route"></select></label><label>Profile <select id="profile"></select></label>
<button id="activate">Activate with concurrency check</button><button id="rollback">Rollback to selected version</button><button id="disable">Emergency disable selected profile</button>
<details><summary>Validate and save a bounded route version</summary><label>Task <select id="routeTask"><option>draft</option><option>summarize</option><option>translate</option><option>evaluate</option><option>answer-with-evidence</option><option>embedding</option></select></label><label>Version <input id="routeVersion" value="editorial.v1"></label><label>Prompt version <input id="promptVersion" value="generated-text.v1"></label><label>Run limit <input id="runLimit" type="number" value=".1" min=".001" max="100" step=".001"></label><label>Currency <select id="currency"><option>USD</option><option>INR</option></select></label><label>Deadline seconds <input id="deadline" type="number" value="60" min="5" max="300"></label><button id="routeSave">Validate qualification and save immutable version</button></details></section>
<script>
const el=id=>document.getElementById(id);let packet=null,reports=[],providerState=null;
function root(){return '/api/v1/editorial/tenants/'+encodeURIComponent(el('tenant').value)+'/universes/'+encodeURIComponent(el('universe').value);}
async function call(path,body){const r=await fetch(path,{method:body===undefined?'GET':'POST',credentials:'same-origin',headers:body===undefined?{}:{'Content-Type':'application/json','X-ContentOS-Staff':'1'},body:body===undefined?undefined:JSON.stringify(body)});if(!r.ok)throw Error((await r.json()).error||'Request rejected');return r.status===204?null:r.json();}
function select(id,rows,label,none=false){const s=el(id);s.replaceChildren();if(none){const o=document.createElement('option');o.value='';o.textContent='None';s.append(o);}for(const r of rows){const o=document.createElement('option');o.value=r.id;o.textContent=label(r);s.append(o);}}
async function action(f){try{el('status').textContent='Working…';await f();el('status').textContent='Saved or loaded. No external publication performed.';}catch(e){el('status').textContent=e.message;}}
function cases(){const r=reports.find(x=>x.id===el('report').value);select('case',(r?.results||[]).map(x=>({id:x.caseKey})),x=>x.id);}
async function inspect(){packet=await call(root()+'/items/'+el('item').value);el('state').textContent=packet.state+' / revision '+packet.current?.version+' / '+(packet.highRisk?'Human approval required':'Human review required');el('blocks').textContent=packet.blocks.join('; ');el('title').value=packet.current?.title||'';el('body').value=packet.current?.body||'';el('previous').value=packet.previous?.body||'';el('kind').value=packet.current?.kind||'Fiction';el('rights').value=packet.current?.rightsStatus||'Unverified';el('provenance').value=packet.current?.provenance||'';
el('detail').textContent=JSON.stringify({citations:packet.citations,claims:packet.claims,disagreements:packet.disagreements,variants:packet.variants,episodes:packet.episodes,productionRuns:packet.productionRuns,evaluations:packet.evaluations,factoryHistory:packet.factoryHistory},null,2);el('lineage').textContent=JSON.stringify({lineage:packet.lineage,approvals:packet.approvals,copies:packet.copies,history:packet.history},null,2);el('lineageLinks').replaceChildren();for(const n of packet.lineage){const a=document.createElement('a');a.href='/api/v1/core/tenants/'+encodeURIComponent(el('tenant').value)+'/universes/'+encodeURIComponent(el('universe').value)+'/content/'+n.contentId;a.textContent=n.format+' revision '+n.version+' / '+n.contentId;const p=document.createElement('p');p.append(a);el('lineageLinks').append(p);}el('assets').replaceChildren();for(const a of packet.assets){const p=document.createElement('p');p.textContent=a.slot+' / '+a.sha256+' / '+a.rightsStatus;const link=document.createElement('a');link.href=root()+'/assets/'+a.id+'/preview';link.textContent='Open scoped preview';p.append(link);if(a.mediaType==='audio/wav'){const player=document.createElement('audio');player.controls=true;player.src=link.href;p.append(player);}if(a.mediaType==='image/png'){const image=document.createElement('img');image.alt=a.slot;image.src=link.href;image.style.maxWidth='300px';p.append(image);}el('assets').append(p);}}
async function queues(){const [tasks,trends]=await Promise.all([call(root()+'/corrections'),call(root()+'/trends')]);el('corrections').replaceChildren();for(const t of tasks){const p=document.createElement('p');p.textContent=t.kind+' / '+t.state+' / content '+t.contentId+' / '+t.reason;const attempts=document.createElement('pre');attempts.textContent=JSON.stringify(t.attempts||[],null,2);p.append(attempts);for(const choice of t.kind==='Internal'?['Resolve','Withdraw']:['Attempted','Unknown','Unsupported','Confirmed']){const b=document.createElement('button');b.textContent=choice;b.onclick=()=>action(async()=>{await call(root()+'/corrections/'+t.id+'/resolve',{operationId:crypto.randomUUID(),expectedRowVersion:t.rowVersion,action:choice,evidenceReference:el('evidence').value,replacementContentId:choice==='Resolve'?(el('replacement').value||null):null});await load();});p.append(b);}el('corrections').append(p);}
el('trends').replaceChildren();for(const t of trends){const p=document.createElement('article');p.textContent=t.input.headline+' / '+t.state+' / expires '+t.input.expiresUtc+' / estimate '+t.input.estimatedCost+' '+t.input.currency+' / '+t.blocks.join('; ');const pre=document.createElement('pre');pre.textContent=JSON.stringify({sources:t.input.sourceSnapshotIds,claims:t.input.claimRevisionIds,lesson:t.input.lessonVariantId,script:t.input.scriptPreview,cast:t.castPreview},null,2);p.append(pre);for(const decision of ['Approve','Hold','Reject']){const b=document.createElement('button');b.textContent=decision;b.onclick=()=>action(async()=>{await call(root()+'/trends/'+t.id+'/review',{operationId:crypto.randomUUID(),expectedRowVersion:t.rowVersion,decision,evidenceReference:el('evidence').value});await queues();});p.append(b);}el('trends').append(p);}}
async function load(){const selected=el('item').value;const [items,catalog,evaluations]=await Promise.all([call(root()+'/items'),call('/api/v1/core/tenants/'+el('tenant').value+'/universes/'+el('universe').value+'/catalog'),call('/api/v1/evaluation/tenants/'+el('tenant').value+'/universes/'+el('universe').value+'/reports')]);reports=evaluations;select('item',items,x=>x.key+' / '+x.state);if(items.some(x=>x.id===selected))el('item').value=selected;select('subject',catalog.subjects,x=>x.name);select('audience',catalog.manifest.audiences,x=>x.name);select('locale',catalog.locales.map(id=>({id})),x=>x.id);select('report',reports,x=>x.id+' / '+x.qualification.status,true);cases();await queues();if(items.length)await inspect();}
el('load').onclick=()=>action(load);el('inspect').onclick=()=>action(inspect);el('report').onchange=cases;
el('edit').onclick=()=>action(async()=>{packet=await call(root()+'/items/'+packet.id+'/edit',{operationId:crypto.randomUUID(),expectedRowVersion:packet.rowVersion,title:el('title').value,body:el('body').value,kind:el('kind').value,rightsStatus:el('rights').value,provenance:el('provenance').value});await load();});
el('act').onclick=()=>action(async()=>{await call(root()+'/items/'+packet.id+'/actions',{operationId:crypto.randomUUID(),expectedRowVersion:packet.rowVersion,action:el('action').value,evidenceReference:el('evidence').value,mode:el('mode').value,evaluation:el('report').value?{reportId:el('report').value,caseKey:el('case').value}:null,scheduledUtc:el('scheduled').value?el('scheduled').value+'Z':null,channel:'LocalPreview'});await load();});
el('start').onclick=()=>action(async()=>{await call(root()+'/items',{operationId:crypto.randomUUID(),key:el('key').value,format:el('format').value,brief:el('brief').value,contentId:el('existing').value||null,draft:el('existing').value?null:{operationId:crypto.randomUUID(),subjectId:el('subject').value,audienceId:el('audience').value,localeId:el('locale').value,title:el('title').value,body:el('body').value,kind:el('kind').value,rightsStatus:el('rights').value,provenance:el('provenance').value,publicKnowledge:false},publicIntended:true});await load();});
el('assetSave').onclick=()=>action(async()=>{const file=el('file').files[0];if(!file||file.size>65536)throw Error('Choose a preview file up to65536 bytes.');const bytes=new Uint8Array(await file.arrayBuffer());let raw='';for(const b of bytes)raw+=String.fromCharCode(b);await call(root()+'/items/'+packet.id+'/assets',{operationId:crypto.randomUUID(),expectedRowVersion:packet.rowVersion,slot:el('slot').value,mediaType:el('mime').value,content:btoa(raw),evidenceReference:el('evidence').value});await load();});
el('correct').onclick=()=>action(async()=>{await call(root()+'/corrections',{operationId:crypto.randomUUID(),claimRevisionId:el('claimId').value||null,snapshotId:el('snapshotId').value||null,reason:el('reason').value,evidenceReference:el('evidence').value});await load();});
el('trendSave').onclick=()=>action(async()=>{const data=JSON.parse(el('trendInput').value);data.operationId=crypto.randomUUID();await call(root()+'/trends',data);await queues();});
async function providers(){providerState=await call(root()+'/providers');el('providers').textContent=JSON.stringify(providerState,null,2);select('route',providerState.routes,x=>x.settings.task+' / '+x.settings.version+' / '+(x.active?'Active':'Inactive'));select('profile',providerState.profiles,x=>x.settings.adapter+' / '+x.settings.qualification+' / '+x.settings.evidenceReference);}
el('providersLoad').onclick=()=>action(providers);
async function routeAction(kind){const route=providerState?.routes.find(x=>x.id===el('route').value);const head=providerState?.heads.find(x=>x.task===route?.settings.task);await call(root()+'/routes',{operationId:crypto.randomUUID(),action:kind,routeId:route?.id||'00000000-0000-0000-0000-000000000000',expectedHeadRowVersion:head?.rowVersion||'',profileId:el('profile').value||null});await providers();}
el('activate').onclick=()=>action(()=>routeAction('Activate'));el('rollback').onclick=()=>action(()=>routeAction('Rollback'));el('disable').onclick=()=>action(()=>routeAction('Disable'));
el('routeSave').onclick=()=>action(async()=>{const profile=providerState?.profiles.find(x=>x.id===el('profile').value);if(!profile)throw Error('Load and select a qualified profile.');await call(root()+'/routes',{operationId:crypto.randomUUID(),action:'ValidateAndSave',routeId:'00000000-0000-0000-0000-000000000000',expectedHeadRowVersion:'',settings:{task:el('routeTask').value,version:el('routeVersion').value,profiles:[profile.id],runLimit:Number(el('runLimit').value),currency:el('currency').value,deadlineSeconds:Number(el('deadline').value),promptVersion:el('promptVersion').value,classification:profile.settings.policy.classifications[0],region:profile.settings.policy.region,maxRetentionDays:profile.settings.policy.retentionDays,allowTraining:false,policyVersion:profile.settings.policy.policyVersion,structured:true,streaming:false,tools:false}});await providers();});
async function universes(){select('universe',await call('/api/v1/core/tenants/'+el('tenant').value+'/universes'),x=>x.name);}
el('tenant').onchange=()=>action(universes);action(async()=>{select('tenant',await call('/api/v1/core/tenants'),x=>x.name);await universes();});
</script></body></html>
""";
}
